traps.trap02.txt:
// 切换到map083陆文龙营帐

	If ($Event == 460) @Event460;
	Return;

@Event460:
	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("map083_陆文龙营帐.map");
	LoadNpc("map083.npc");
	LoadObj("map083.obj");
	SetPlayerPos(7, 21);
	SetPlayerDir(3);
	SetNpcRes("独孤剑", "npcres001_独孤剑.ini");
	SetNpcRes("张琳心", "npcres004_张琳心.ini");
	FadeIn();
	
	MoveScreen(3, 2, 50);
	StopMusic();
	PlayMusic("归雁.mp3");
	Say("陆文龙：你叫“苦人儿”？既然你从宋国来，就给我讲讲南朝的故事吧！", 97); 
	Say("苦人儿：既然殿下想听，那在下就讲一个“越鸟南归”的故事。", 63);
	Say("苦人儿：当年越国奇女子西施自愿前往吴国，以美色引诱吴王，她随身带了一只聪明无比的鹦鹉相伴。谁知鹦鹉到了吴国以后，从此一个字都不说，直到十年后再次回到了越国，鹦鹉才重新开始说话……", 63);
	Say("陆文龙：这却是为何，苦人儿？", 97);
	Say("苦人儿：殿下，这是因为鹦鹉不愿讲吴地的话，所以甘愿沉默啊！", 63);
	Say("陆文龙：果然是一只义鸟！苦人儿，你再讲一个吧。", 97);
	Say("苦人儿：好，我就再讲一个“骅骝向北”的故事。", 63);
	Say("苦人儿：当年杨家将和辽国作战，杨家将孟良缴获了一匹辽国的宝马，将马带回东京。不料那宝马整日向北嘶叫，粗细粮草都不沾口，饿了七日，竟自死去……", 63);
	Say("陆文龙：宁死不事二主，真乃烈马！此马也知晓忠义大节，让人钦佩！", 97);
	Say("王佐：正是，将军如此年少却深明大义，前途未可限量也。", 63);
	Say("陆文龙：你的故事很有意思，再给我讲一个吧。", 97);
	Say("王佐：你真的想听？", 63);
	Say("陆文龙：那自然！", 97);
	Say("王佐：好，那我就给你讲一个有人不报父仇，反而认贼作父的故事。", 63);
	Say("陆文龙：快快讲来，这世上居然还有这等无耻之人？", 97);
	Say("王佐：十三年前，金兵初犯中原，宋潞安州守将陆登率兵誓死抵抗，到最后和夫人一起自杀殉国，只留下了一个三岁的孤儿。那金兵的主将见此儿资质甚好，便认做义子带回金国抚养，迄今已有十五年了。那婴儿长至十八岁，学了一身好武艺，可惜不但不知那金将乃是杀父仇人，反而认贼作父，助纣为虐，助金军去攻打自己的国家，实在是让人扼腕叹息啊！", 63);
	Say("陆文龙：大胆！匹夫你敢口出不逊！", 97);
	Say("苦人儿：殿下，不，陆将军，你到现在还不觉悟吗？", 63);
	Say("陆文龙：我，那婴儿，难道……", 97);
	Say("苦人儿：不错，那长至十八岁、认贼作父的婴儿，便是姓陆，名文龙；那杀死婴儿亲生父母的金将，就是正高坐在金兵主帐营内的金兀术！", 63);
	Say("陆文龙：啊——不！不可能！", 97);
	Sleep(500);
	NpcGoto("乳娘", 6, 18);
	SetNpcDir("乳娘", 2);
	Say("乳娘：少爷，这都是真的！老爷和夫人死得好惨啊，我忍辱负重十三年，为的就是把少爷你抚养成人，给老爷和夫人报仇啊。", 0);
	Say("陆文龙：连乳娘也这么说，难道……我真的是陆登之子？！怎么会这样……", 97);
	Say("苦人儿：在下王佐，和令尊当年乃是八拜之交。今日我犯死至此，只希望陆将军你能迷途之返，不要铸成大错！", 63);
	Say("乳娘：少爷，其实我早就想把实情告诉少爷，但害怕少爷沉不住气，反而遭了金兀术的毒手。当年老爷曾留下一柄“丹心剑”，剑柄中留下了血书，好让少爷成人后继承他老人家的遗志……", 0);
	Say("陆文龙：那剑呢？", 97);
	Say("乳娘：数年前，曾有一位蒙面义士想从金兵大营中救走少爷，不想金兵防卫甚严。那位义士见无法救人，便将“丹心剑”带走了。现在，已不知下落……", 0);	
	Sleep(500);
	
	Say("独孤剑：丹心剑就在此！", 1);
	SetPlayerScn();
	PlayerGoto(5, 19);
	SetPlayerDir(3);
	SetNpcKind("张琳心", 1);
	NpcGoto("张琳心", 5, 20);
	SetNpcDir("张琳心", 4);
	Watch("陆文龙", "独孤剑", 0);
	Say("陆文龙：你是谁？", 97);
	Say("独孤剑：在下衡山独孤剑，这丹心剑这些年就在我衡山派中，如今可以物归原主了。", 1);
	Say("王佐：快看看里面是否有令尊留下的书信？", 63);
	
	NpcSpecialAction("独孤剑", "mpc029_1.asf");
	SetNpcActionFile("陆文龙", 0, "mpc029_3.asf");
	SetNpcActionFile("陆文龙", 1, "mpc029_3.asf");
	NpcSpecialAction("陆文龙", "mpc029_2.asf");
	Sleep(4000);
	Say("陆文龙：果然有封血书！", 97);
	Say("文龙我儿：今金兵来犯，战事日危。乃父苦战数月，自度独力难支，唯以死殉城，以成忠义。汝乃陆家血脉所托，痛念万千，今嘱乳娘，抚恤存年，全我一脉。吾儿切切谨记，仁义立身，精忠报国。为父谆谆，勿负所望。父登绝笔", 0);
	SetNpcActionFile("陆文龙", 0, "npc019_st.asf");
	SetNpcActionFile("陆文龙", 1, "npc019_pst.asf");
	NpcSpecialAction("陆文龙", "mpc029_4.asf");
	Sleep(1500);
	
	DelGoods("Goods048_丹心剑.ini");
	Say("陆文龙：父亲！母亲！孩儿不肖——", 97);
	Watch("陆文龙", "王佐", 0);
	Say("陆文龙：我这就去杀了兀术给父母报仇！", 97);
	Say("王佐：将军且慢，兀术帐下人多，将军此去只怕大事不成还反受其害，将军且随我去投了岳元帅，再从长计议，如何？", 63);
	Say("独孤剑：王将军言之有理，元帅正为王将军的下落担忧，你们此时去见元帅，元帅一定很高兴。", 1);
	SetNpcDir("陆文龙", 6);
	Say("陆文龙：也好，我有一份关系到八十万宋军性命的重要军情要马上向岳元帅禀报。", 97);
	Say("王佐：什么事情如此严重？", 63);
	Say("陆文龙：兀术从黄龙府运来了三百门威力极大的火炮，唤作“铁浮陀”，炮弹所到之处天崩地裂，片瓦无存，人畜皆可炸为齑粉。这批“铁浮陀”由兀术的亲信南宫灭押送，今晚到达，若不马上给岳元帅报信，明早十二座宋营恐怕就要灰飞烟灭了！", 97);
	Say("独孤剑：南宫灭要来？此人武功高强，他到后我们就难以脱身了。请陆公子先带乳娘和王将军去宋营通知岳元帅，我和张姑娘断后，再寻机毁去火炮。", 6);
	Watch("陆文龙", "独孤剑", 0);
	Say("陆文龙：可是这样你和张姑娘就太危险了！", 97);
	Say("独孤剑：我和张姑娘有武功防身，寻常士兵奈何不了我们，事成之后当可全身而退。", 1);
	Say("王佐：也好，现在情况紧急，少将军就不要推脱了。我护送少将军和乳娘离开，这里就拜托独孤少侠和张姑娘了，两位请多加小心！咱们后会有期！", 63);
	Say("独孤剑：好！后会有期！", 1);
	PlayerGoto(5, 21);
	SetPlayerDir(4);
	NpcGotoEx("陆文龙", 7, 22);
	NpcGotoEx("乳娘", 7, 21);
	NpcGoto("王佐", 8, 20);
	Sleep(200);
	DelNpc("陆文龙");
	DelNpc("乳娘");
	DelNpc("王佐");
	SaveNpc();
	
	Watch("独孤剑", "张琳心", 0);
	Say("张琳心：我们应该赶快去阻止金兀术和南宫灭布置铁浮陀对付岳元帅，晚了就来不及了！", 21);
	Say("独孤剑：对！", 1);
	SetNpcKind("张琳心", 3);
	SetNpcRelation("张琳心", 0);
	Assign($Event, 470); 
	Memo("独孤剑和张琳心找到陆文龙营帐，向陆文龙证实了他真实的身份是宋将陆登之子。陆文龙决定立刻去投奔岳飞。众人离去后，独孤剑和张琳心赶去阻止兀术和南宫灭布置火炮对付岳家军。");
	Return;

